svg.metadata:
flowchart TB
  A["apiContract: method, path, input and output schemas"]
  B["Serv / Kit: mount real handlers"]
  C["API Client: infer arguments and response types"]
  D["Server: validate, authenticate, authorize, then run business logic"]
  E["Client: send HTTP and inspect HaiResult"]
  A --> B
  A --> C
  B --> D
  C --> E
  E -->|"actual request"| D
  classDef default fill:#edf3ff,stroke:#476aab,color:#172b4d,stroke-width:1.5px;
  classDef good fill:#e9f6ef,stroke:#28734e,color:#17452f,stroke-width:1.5px;
  classDef stop fill:#fff0f0,stroke:#af4040,color:#742b2b,stroke-width:1.5px;
  classDef pending fill:#fff6df,stroke:#a07827,color:#654b18,stroke-width:1.5px;
  class D good;
